// Room data validity: every registered room (layout generated by its Blender build
// script, look and anchors hand-tuned) is checked for things the engine relies on.
// Run: node src/world3d/engine/rooms/rooms.selftest.mjs
import assert from "node:assert/strict";
import { existsSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { ROOMS, ROOM_IDS, DEFAULT_ROOM, getRoom } from "./index.js";
import { groundAt } from "./ground.js";
import { makeBox, pushOutOfBox } from "../collision.js";
import { PIECES, okeyCell, cardCell, okeySet } from "../piecesData.js";

const here = dirname(fileURLToPath(import.meta.url));
const publicDir = join(here, "..", "..", "..", "..", "public", "world3d");
const AVATAR_R = 0.24;
const fin = (v) => Number.isFinite(v);

assert.deepEqual(ROOM_IDS.sort(), ["camp", "cinema", "game-room", "living-room"]);
assert.equal(getRoom("nope").id, DEFAULT_ROOM, "unknown ids fall back to the living room");
assert.equal(DEFAULT_ROOM, "living-room");

const inBounds = (b, x, z, m = 0) => x >= b.minX + m && x <= b.maxX - m && z >= b.minZ + m && z <= b.maxZ - m;
const blocked = (boxes, x, z, r = AVATAR_R) => boxes.some((b) => {
  const p = pushOutOfBox(x, z, r, b);
  return Math.abs(p[0] - x) > 1e-6 || Math.abs(p[1] - z) > 1e-6;
});

for (const id of ROOM_IDS) {
  const room = ROOMS[id];
  const L = room.layout;
  const where = (s) => `${id}: ${s}`;
  assert.equal(room.id, id);
  assert.ok(L, where("layout module present (run the room's build script)"));
  // GLB shipped next to the living room, within the size budget
  const glb = join(publicDir, room.glb);
  assert.ok(existsSync(glb), where(`${room.glb} exists`));
  assert.ok(statSync(glb).size < 5.0 * 1024 * 1024, where(`${room.glb} under 5 MB`));
  // look: the engine reads these without defaults
  const look = room.look;
  for (const k of ["exposure", "contrast", "curves", "vignette", "bloom", "dof", "lights"]) assert.ok(look[k] != null, where(`look.${k}`));
  // bounds
  const b = L.bounds;
  assert.ok(b && b.maxX - b.minX > 3 && b.maxZ - b.minZ > 3 && b.maxY > 2.4, where("bounds sane"));
  // colliders
  const boxes = L.colliders.map((c) => makeBox(c.cx, c.cz, c.hx, c.hz, c.angle));
  for (const c of L.colliders) {
    assert.ok([c.cx, c.cz, c.hx, c.hz, c.angle].every(fin), where(`collider ${c.name} finite`));
    assert.ok(c.hx > 0.05 && c.hz > 0.05 && c.hx < 6 && c.hz < 6, where(`collider ${c.name} size`));
    assert.ok(inBounds(b, c.cx, c.cz), where(`collider ${c.name} inside bounds`));
  }
  // seats
  const names = new Set();
  assert.ok(L.seats.length >= 4, where("has seats"));
  for (const s of L.seats) {
    assert.ok(!names.has(s.name), where(`seat ${s.name} unique`));
    names.add(s.name);
    assert.match(s.name, /^SEAT_.+_\d+$/, where(`seat ${s.name} name`));
    const [x, y, z] = s.pos;
    assert.ok([x, y, z, s.yaw, s.height].every(fin), where(`seat ${s.name} finite`));
    assert.ok(inBounds(b, x, z, 0.1), where(`seat ${s.name} inside bounds`));
    assert.ok(s.height > 0.35 && s.height < 0.6, where(`seat ${s.name} height ${s.height} fits the sit clip`));
    assert.ok(Math.abs(y - groundAt(L.floors, x, z)) < 0.02, where(`seat ${s.name} stands on its floor`));
    assert.ok(typeof s.type === "string" && s.type.length, where(`seat ${s.name} type`));
    // the avatar walks to the approach point (or just in front of the seat) before sitting
    const ax = s.approach ? s.approach[0] : x + Math.sin(s.yaw) * 0.64;
    const az = s.approach ? s.approach[1] : z + Math.cos(s.yaw) * 0.64;
    assert.ok(inBounds(b, ax, az, AVATAR_R), where(`seat ${s.name} approach inside bounds`));
    assert.ok(!blocked(boxes, ax, az), where(`seat ${s.name} approach point is walkable`));
  }
  // spawns
  assert.ok(L.spawns.length >= 4, where("spawn points"));
  for (const p of L.spawns) {
    assert.ok(inBounds(b, p[0], p[2], AVATAR_R), where(`spawn ${p} inside bounds`));
    assert.ok(!blocked(boxes, p[0], p[2]), where(`spawn ${p} not inside a collider`));
    assert.ok(Math.abs(p[1] - groundAt(L.floors, p[0], p[2])) < 0.02, where(`spawn ${p} on the floor`));
  }
  // hero camera
  const h = L.hero;
  assert.ok(h && h.pos.every(fin) && h.target.every(fin), where("hero camera"));
  assert.ok(inBounds(b, h.pos[0], h.pos[2]) && h.pos[1] < b.maxY, where("hero camera inside the room"));
  assert.ok(h.fov > 0.6 && h.fov < 1.6, where("hero fov"));
  const dist = Math.hypot(h.pos[0] - h.target[0], h.pos[1] - h.target[1], h.pos[2] - h.target[2]);
  assert.ok(dist > 1.6 && dist < 9, where("hero distance within the orbit camera limits"));
}

// cinema: the screen anchor is ready for a 16:9 video texture; tiered rows
{
  const L = ROOMS.cinema.layout;
  const sc = L.anchors.screen;
  assert.equal(sc.mesh, "SCREEN_main");
  assert.equal(sc.material, "EMIT_screen");
  assert.equal(sc.aspect, "16:9");
  assert.ok(Math.abs(sc.width / sc.height - 16 / 9) < 0.01, "screen 16:9");
  assert.ok(L.anchors.seatRows.length === 3 && L.anchors.seatRows.every((r) => r.length === 6), "3 rows x 6 seats");
  assert.ok(L.floors.length >= 3, "tiers");
  const ys = L.anchors.seatRows.map((r) => L.seats.find((s) => s.name === r[0]).pos[1]);
  assert.ok(ys[0] < ys[1] && ys[1] < ys[2], "rows rise towards the back");
}

// game room: okey 4 seats + racks, blackjack 5 players + robot dealer, tavla + chess boards
{
  const L = ROOMS["game-room"].layout;
  const seatNames = new Set(L.seats.map((s) => s.name));
  const t = Object.fromEntries(L.anchors.tables.map((x) => [x.game, x]));
  assert.equal(t.okey.seats.length, 4);
  assert.equal(t.okey.racks.length, 4);
  assert.equal(t.blackjack.seats.length, 5, "five blackjack players (scene-2.jpg, GAMES_PROTOCOL.md)");
  assert.equal(t.blackjack.spots.players.length, 5);
  assert.ok(L.anchors.dealer?.glb === "robot-dealer.glb");
  assert.equal(t.tavla.seats.length, 2);
  assert.equal(t.chess.seats.length, 2);
  for (const x of Object.values(t)) for (const n of x.seats) assert.ok(seatNames.has(n), `table seat ${n} exists`);
  for (const f of ["robot-dealer.glb", "okey.glb", "cards.glb", "tavla.glb", "chess.glb"]) assert.ok(existsSync(join(publicDir, f)), `${f} shipped`);
}

// camp: the fire and its runtime spec, benches with their seats
{
  const C = ROOMS.camp;
  const f = C.layout.anchors.fire;
  assert.ok(f && f.flameMeshes.length >= 2 && f.lightPos.every(fin));
  const spec = C.fx.fire;
  assert.ok(spec.light.intensity > 0 && spec.light.range > 2 && spec.layer.level > 0);
  for (const p of spec.particles) {
    assert.ok(p.capacity > 0 && p.emitRate > 0 && p.maxLife >= p.minLife && p.maxSize >= p.minSize, `particles ${p.name}`);
    for (const k of ["emitBox", "direction1", "direction2", "color1", "color2", "colorDead"]) assert.ok(Array.isArray(p[k]), `particles ${p.name}.${k}`);
  }
  assert.equal(Object.keys(C.layout.anchors.benches).length, 4);
}

// game pieces: a full okey set, every card has a cell inside the atlas
{
  const set = okeySet();
  assert.equal(set.length, 106);
  assert.equal(set.filter((t) => t.color === "false").length, 2);
  const cells = new Set(set.map((t) => okeyCell(t.color, t.number)));
  assert.equal(cells.size, 53);
  const okeyMax = PIECES.okey.grid.cols * PIECES.okey.grid.rows;
  for (const c of cells) assert.ok(c >= 0 && c < okeyMax);
  const cardMax = PIECES.cards.grid.cols * PIECES.cards.grid.rows;
  const cardCells = new Set();
  for (const s of PIECES.cards.suits) for (const r of PIECES.cards.ranks) cardCells.add(cardCell(s, r));
  assert.equal(cardCells.size, 52);
  for (const c of [...cardCells, cardCell("back"), cardCell("score", 0), cardCell("score", 1)]) assert.ok(c >= 0 && c < cardMax);
  assert.equal(PIECES.tavla.points.length, 24);
  assert.equal(Object.values(PIECES.tavla.start.light).reduce((a, b) => a + b, 0), 15);
  assert.equal(Object.values(PIECES.tavla.start.dark).reduce((a, b) => a + b, 0), 15);
  assert.equal(PIECES.okey.rack.slots, 15);
}

console.log("rooms.selftest: ok");
